/* Novedades: conservar siempre la identidad exacta de la fila (tarea_id + SIGEST + etapa). */
let ccNoveltyTaskId = 0;
const ccLoadNoveltiesExact = async function(sigest, taskStage, taskId) {
    const operation = async () => {
        const params = new URLSearchParams({sigest:String(sigest), etapa:String(taskStage), tarea_id:String(taskId || 0)});
        const response = await fetch('?accion=novedades&' + params.toString(), {headers:{Accept:'application/json'}});
        const payload = await response.json().catch(() => ({}));
        if (!response.ok || !payload.ok) throw new Error(payload.error || 'No se pudieron cargar las novedades.');
        ccNoveltyTaskId = Number(payload.task?.tarea_id || taskId || 0);
        const resolvedSigest = String(payload.task?.sigest || sigest), resolvedStage = String(payload.task?.etapa || taskStage);
        $('noveltySubtitle').textContent = 'SIGEST ' + resolvedSigest + ' · ' + String(payload.task?.titulo || '');
        $('noveltyForm').elements.sigest.value = resolvedSigest;
        $('noveltyForm').elements.etapa.value = resolvedStage;
        renderNovelties(payload.novedades || []);
        if (payload.avisos_pendientes !== null && payload.avisos_pendientes !== undefined) setAlertCount(payload.avisos_pendientes);
        return payload;
    };
    return window.NexoLoading ? window.NexoLoading.run(operation, {message:'Cargando novedades', timeout:30000}) : operation();
};
loadNovelties = ccLoadNoveltiesExact;
openNovelties = async function(sigest, taskStage, taskId) {
    const row = rows.find(item => item.sigest === String(sigest) && item.stage === String(taskStage));
    ccNoveltyTaskId = Number(taskId || row?.task_id || 0);
    $('noveltyModal').hidden = false; $('noveltySubtitle').textContent = 'SIGEST ' + String(sigest) + (row?.titulo ? ' · ' + row.titulo : ''); $('noveltyList').innerHTML = '<p class="muted">Cargando novedades…</p>'; $('noveltyFeedback').textContent = '';
    try { await loadNovelties(sigest, taskStage, ccNoveltyTaskId); }
    catch (error) { $('noveltyList').innerHTML = '<p class="error">' + esc(error.message || 'No se pudieron cargar las novedades.') + '</p>'; }
};
closeNovelties = function() { ccNoveltyTaskId = 0; $('noveltyModal').hidden = true; $('noveltyList').replaceChildren(); $('noveltyFeedback').textContent = ''; };
saveNovelty = async function(e) {
    e.preventDefault(); const form=e.currentTarget, button=form.querySelector('button[type="submit"]'), feedback=$('noveltyFeedback');
    const sigest=form.elements.sigest.value, taskStage=form.elements.etapa.value, type=form.elements.tipo.value, text=form.elements.texto.value.trim(); feedback.textContent='';
    const operation=async()=>{const response=await fetch('?accion=novedad_guardar',{method:'POST',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},body:new URLSearchParams({csrf:management.csrf||'',tarea_id:String(ccNoveltyTaskId||0),sigest,etapa:taskStage,tipo:type,texto:text})});const payload=await response.json().catch(()=>({}));if(!response.ok||!payload.ok)throw new Error(payload.error||'No se pudo guardar la novedad.');const row=rows.find(r=>r.sigest===sigest&&r.stage===taskStage);if(row){row.task_id=Number(payload.tarea_id||ccNoveltyTaskId||0);row.novedades_total=payload.novedades_total;row.avisos_pendientes=payload.avisos_tarea;ccNoveltyTaskId=row.task_id}if(type==='REQUIERE_ATENCION')setAlertCount(management.avisos_pendientes+1);form.elements.texto.value='';render();closeNovelties();showToast(payload.message);return payload};
    try { if(window.NexoLoading) await window.NexoLoading.run(operation,{message:'Guardando novedad',button,timeout:30000}); else await operation(); } catch(error) { if(!window.NexoLoading?.isSessionExpired(error)) feedback.textContent=error.message||'No se pudo guardar la novedad.'; }
};
