registerGestion=async function(row,button,gestionDate=''){if(row.gestionada||(!row.puede_gestionar&&!row.puede_gestionar_admin))return;button.disabled=true;const operation=async()=>{const params={csrf:management.csrf||'',sigest:row.sigest,etapa:row.stage};if(window.ccIsAdmin)params.fecha_gestion=gestionDate;const response=await fetch('?accion=gestionar',{method:'POST',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},body:new URLSearchParams(params)});const payload=await response.json().catch(()=>({}));if(!response.ok||!payload.ok)throw new Error(payload.error||'No se pudo registrar la gestión.');if(payload.tarea)Object.assign(row,payload.tarea);else{row.gestionada=true;row.gestion_usuario_id=payload.gestion?.usuario_id||management.actor_id;row.gestion_usuario_nombre=payload.gestion?.usuario_nombre||'Usuario';row.gestion_registrado_por_id=management.actor_id;row.gestion_registrado_por_nombre=management.actor_name||'';row.gestion_fecha_gestion=payload.gestion?.fecha_gestion||gestionDate}refreshCascades(true);render();showToast(payload.message||'Gestión registrada.');return payload};try{if(window.NexoLoading)await window.NexoLoading.run(operation,{message:'Registrando gestión',button,timeout:30000});else await operation()}catch(e){if(!window.NexoLoading?.isSessionExpired(e))showToast(e.message||'No se pudo registrar la gestión.',false)}finally{button.disabled=false}};
unregisterGestion=async function(row,button){if(!row.gestionada||(!window.ccIsAdmin&&row.gestion_registrado_por_id!==String(management.actor_id||'')))return;button.disabled=true;const operation=async()=>{const response=await fetch('?accion=desgestionar',{method:'POST',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},body:new URLSearchParams({csrf:management.csrf||'',sigest:row.sigest,etapa:row.stage})});const payload=await response.json().catch(()=>({}));if(!response.ok||!payload.ok)throw new Error(payload.error||'No se pudo desmarcar la gestión.');if(payload.tarea)Object.assign(row,payload.tarea);refreshCascades(true);render();showToast(payload.message||'Gestión desmarcada.');return payload};try{if(window.NexoLoading)await window.NexoLoading.run(operation,{message:'Desmarcando gestión',button,timeout:30000});else await operation()}catch(e){if(!window.NexoLoading?.isSessionExpired(e))showToast(e.message||'No se pudo desmarcar la gestión.',false)}finally{button.disabled=false}};
const ccAdminGestionColumn=addGestionColumn;addGestionColumn=function(){ccAdminGestionColumn();if(!window.ccIsAdmin)return;document.querySelectorAll('#tbody tr').forEach(tr=>{const link=tr.querySelector('[data-id]'),row=rows.find(item=>item.sigest===link?.dataset.id&&item.stage===link?.dataset.detailStage),cell=tr.querySelector('[data-gestion-cell]');if(!row||!cell||!row.puede_gestionar_admin||cell.querySelector('[data-gestion-action]'))return;const pending=cell.querySelector('.gestion-pending');if(!pending)return;const button=document.createElement('button');button.type='button';button.className='gestion-dot gestion-pending';button.title='Registrar gestión';button.setAttribute('aria-label','Registrar gestión');button.dataset.gestionAction=taskKey(row);pending.replaceWith(button);button.onclick=()=>openGestionModal(row,'marcar',button)})};
openGestionPopover=function(button,row){const pop=ensureGestionPopover();gestionPopoverAnchor=button;clearTimeout(gestionPopoverHideTimer);const workDate=fmtDate(row.gestion_fecha_gestion||row.gestion_fecha)||'—',registered=fmtDateTime(row.gestion_registrado_en||row.gestion_fecha),parts=registered.split(' '),date=parts[0]||'—',time=parts[1]||'—',canUndo=window.ccIsAdmin||row.gestion_registrado_por_id===String(management.actor_id||'');pop.innerHTML='<div class="gestion-popover-title"><span class="gestion-popover-dot"></span><strong>Gestión realizada</strong></div><dl><dt>Acción</dt><dd>'+esc(row.gestion_tipo||'Gestionada')+'</dd><dt>Por</dt><dd>'+esc(row.gestion_usuario_nombre||'Usuario')+'</dd><dt>Fecha de gestión</dt><dd>'+esc(workDate)+'</dd><dt>Registrado</dt><dd>'+esc(date+(time?' '+time:''))+'</dd>'+(row.gestion_registrado_por_id&&row.gestion_registrado_por_id!==row.gestion_usuario_id?'<dt>Registrado por</dt><dd>'+esc(row.gestion_registrado_por_nombre||'Administrador')+'</dd>':'')+'</dl>'+(canUndo?'<button type="button" class="gestion-popover-action">Desmarcar gestión</button>':'');pop.querySelector('.gestion-popover-action')?.addEventListener('click',e=>{e.stopPropagation();closeGestionPopover();openGestionModal(row,'desmarcar',button)});positionGestionPopover(button)};
const ccGestionColorStyle=document.createElement('style');ccGestionColorStyle.textContent='.gestion-critical{background:#dc2626!important;border-color:#b91c1c!important}';document.head.appendChild(ccGestionColorStyle);
const ccGestionColorFinal=addGestionColumn;addGestionColumn=function(){ccGestionColorFinal();document.querySelectorAll('#tbody tr').forEach(tr=>{const link=tr.querySelector('[data-id]'),row=rows.find(item=>item.sigest===link?.dataset.id&&item.stage===link?.dataset.detailStage);if(row&&!row.gestionada&&row.sem?.class==='red')tr.querySelector('.gestion-pending')?.classList.add('gestion-critical')})};

// El proxy exige el CSRF de la sesión local también para la descarga XLSX.
const ccExportButtonFinal = $('exportBtn');
if (ccExportButtonFinal) ccExportButtonFinal.onclick = async () => {
    try {
        const operation = () => window.NexoLoading.download('?accion=exportar', {method:'POST', body:new URLSearchParams({csrf:management.csrf||'', keys:JSON.stringify(filtered().map(taskKey))}), filename:'control_certificacion_ocras.xlsx'});
        if (window.NexoLoading) await window.NexoLoading.run(operation, {message:'Generando XLSX', button:ccExportButtonFinal, timeout:120000});
        else await operation();
    } catch (error) { if (!window.NexoLoading?.isSessionExpired(error)) showToast('No se pudo generar el XLSX.', false); }
};
